import{_ as a,a0 as s,w as p,s as l,ao as u,I as i,x as n,a1 as r,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"Linux有问必答：如何在Linux中修改环境变量PATH | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在Linux中修改环境变量PATH | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在Linux中修改环境变量PATH | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在Linux中修改环境变量PATH | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150413 Linux FAQs with Answers--How to change PATH environment variable on Linux","title":"Linux有问必答：如何在Linux中修改环境变量PATH","tag":"201505","desc":""},"relativePath":"201505/20150413 Linux FAQs with Answers--How to change PATH environment variable on Linux.md","filePath":"[post].md"}'),d={name:"201505/20150413 Linux FAQs with Answers--How to change PATH environment variable on Linux.md"};function T(x,e,b,m,A,h){const o=s("Link");return p(),l("div",null,[e[13]||(e[13]=u(`<h1 id="linux有问必答-如何在linux中修改环境变量path" tabindex="-1">Linux有问必答：如何在Linux中修改环境变量PATH <a class="header-anchor" href="#linux有问必答-如何在linux中修改环境变量path" aria-label="Permalink to “Linux有问必答：如何在Linux中修改环境变量PATH”">​</a></h1><blockquote><p><strong>提问</strong>: 当我试着运行一个程序时，它提示“command not found”。 但这个程序就在/usr/local/bin下。我该如何添加/usr/local/bin到我的PATH变量下，这样我就可以不用指定路径来运行这个命令了。</p></blockquote><p>在Linux中，PATH环境变量保存了一系列的目录用于用户在输入的时候搜索命令。PATH变量的值由一系列的由分号分隔的绝对路径组成。每个用户都有特定的PATH环境变量（由系统级的PATH变量初始化）。</p><p>要检查用户的环境变量，用户模式下运行下面的命令：</p><pre><code>$ echo $PATH
</code></pre><hr><pre><code>/usr/lib64/qt-3.3/bin:/bin:/usr/bin:/usr/sbin:/sbin:/home/xmodulo/bin
</code></pre><p>或者运行：</p><pre><code>$ env | grep PATH
</code></pre><hr><pre><code>PATH=/usr/lib64/qt-3.3/bin:/bin:/usr/bin:/usr/sbin:/sbin:/home/xmodulo/bin
</code></pre><p>如果你的命令不存在于上面任何一个目录内，shell就会抛出一个错误信息：“command not found”。</p><p>如果你想要添加一个另外的目录（比如：/usr/local/bin）到你的PATH变量中，你可以用下面这些命令。</p><h3 id="为特定用户修改path环境变量" tabindex="-1">为特定用户修改PATH环境变量 <a class="header-anchor" href="#为特定用户修改path环境变量" aria-label="Permalink to “为特定用户修改PATH环境变量”">​</a></h3><p>如果你只想在当前的登录会话中临时地添加一个新的目录（比如：/usr/local/bin）给用户的默认搜索路径，你只需要输入下面的命令。</p><pre><code>$ PATH=$PATH:/usr/local/bin
</code></pre><p>检查PATH是否已经更新：</p><pre><code>$ echo $PATH
</code></pre><hr><pre><code>/usr/lib64/qt-3.3/bin:/bin:/usr/bin:/usr/sbin:/sbin:/home/xmodulo/bin:/usr/local/bin
</code></pre><p>更新后的PATH会在当前的会话一直有效。然而，更改将在新的会话中失效。</p><p>如果你想要永久更改PATH变量，用编辑器打开~/.bashrc (或者 ~/.bash_profile)，接着在最后添加下面这行。</p><pre><code>export PATH=$PATH:/usr/local/bin
</code></pre><p>接着运行下面这行永久激活更改：</p><pre><code>$ source ~/.bashrc (或者 source ~/.bash_profile)
</code></pre><h3 id="改变系统级的环境变量" tabindex="-1">改变系统级的环境变量 <a class="header-anchor" href="#改变系统级的环境变量" aria-label="Permalink to “改变系统级的环境变量”">​</a></h3><p>如果你想要永久添加/usr/local/bin到系统级的PATH变量中，像下面这样编辑/etc/profile。</p><pre><code>$ sudo vi /etc/profile
</code></pre><hr><pre><code>export PATH=$PATH:/usr/local/bin
</code></pre><p>你重新登录后，更新的环境变量就会生效了。</p><hr>`,32)),i("p",null,[e[1]||(e[1]=n("via: ",-1)),r(o,{href:"http://ask.xmodulo.com/change-path-environment-variable-linux.html"},{default:t(()=>[...e[0]||(e[0]=[n("http://ask.xmodulo.com/change-path-environment-variable-linux.html",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=n("作者：",-1)),r(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:t(()=>[...e[2]||(e[2]=[n("Dan Nanni",-1)])]),_:1}),e[6]||(e[6]=n(" 译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:t(()=>[...e[3]||(e[3]=[n("geekpi",-1)])]),_:1}),e[7]||(e[7]=n(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[n("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=n("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[n("LCTT",-1)])]),_:1}),e[11]||(e[11]=n(" 原创翻译，",-1)),r(o,{href:"http://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[n("Linux中国",-1)])]),_:1}),e[12]||(e[12]=n(" 荣誉推出",-1))])])}const L=a(d,[["render",T]]);export{c as __pageData,L as default};
